@startuml

class Hospital {}

class Department {
  + Name : string
}

class Staff {
  + Name : string
}

class Patient {
  + Name : string
}

class MedicalRecord {
  + Id : string
}

class Admission {
  + Date : datetime
  + DischargeDate : datetime
}

class Shift {
  + StartTime : time
  + EndTime : time
}

class EmergencyRoom {}

Hospital "1" *-- "1..*" Department
Department "1" *-- "1..*" Staff
Department "1" *-- "*" Patient
Patient "1" *-- "1" MedicalRecord
Patient "1" -- "*" Admission
Department "0..1" -- "*" Staff : has fixed medical staff
EmergencyRoom "1" -- "*" Staff : works in shifts
EmergencyRoom "1" -- "*" Shift
Staff "1" -- "*" Shift

@enduml

